"""Adds support for collecting the screl log collection on a classical bts
with sbts admin library.
"""


class ClassicalGnbScrelCollectorConfigurator:
    """Class providing screl log collection"""

    def add_screl(self, ne_log_name, ne_log_configuration):
        """Creates the collector for screl log collection on a classical bts
        with the admin library

        :param str ne_log_name: The name of the collector
        :param dict ne_log_configuration: The optional configuration dictionary
        """

        webservice = self.tl_config_information_provider.get_web_service(node_id=self.ne_id)

        screl_collector_config = {
            'name': f'{ne_log_name}',
            'type': 'screl_sbts',
            'webservice': webservice,
            'coverage': 'Full',
            'force': 'False',
            'timeout': 480}

        self._collector_configuration_data.append(screl_collector_config)
        self._collector_configuration_data.add_mapping_entry(
            log_type='screl',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=screl_collector_config)
